    private int permutationIndex;
    private final int[] board;
    private int letter, rotation;
    private int[] shape;
    private int position;
    private int timer;
    private Tetris opponent;
    public boolean gameOver;

    public Tetris() {
        permutationIndex = 7;
        board = EMPTY_BOARD.clone();
        shape = SHAPES[letter = 4][rotation = 0];
        position = 6;
    }

    public void setOpponent(Tetris opponent) {
        this.opponent = opponent;
    }

    public int cell(int x, int y) {
        return board[y * WIDTH + x];
    }

    public void storePiece(int value) {
        board[position + shape[0]] = value;
        board[position + shape[1]] = value;
        board[position + shape[2]] = value;
        board[position + shape[3]] = value;
    }

    public void moveLeft() {
        --position;
        if (board[position + shape[0]] != 0 ||
                board[position + shape[1]] != 0 ||
                board[position + shape[2]] != 0 ||
                board[position + shape[3]] != 0) {
            ++position;
        }
    }

    public void moveRight() {
        ++position;
        if (board[position + shape[0]] != 0 ||
                board[position + shape[1]] != 0 ||
                board[position + shape[2]] != 0 ||
                board[position + shape[3]] != 0) {
            --position;
        }
    }

    public void tick() {
        ++timer;
        if (timer == TICKS_PER_SECOND) {
            moveDown();
        }
    }

    public void moveDown() {
        timer = 0;
        position += WIDTH;
        if (board[position + shape[0]] != 0 ||
                board[position + shape[1]] != 0 ||
                board[position + shape[2]] != 0 ||
                board[position + shape[3]] != 0) {
            position -= WIDTH;
            board[position + shape[0]] = letter;
            board[position + shape[1]] = letter;
            board[position + shape[2]] = letter;
            board[position + shape[3]] = letter;
            int n = 0;
            for (int i = 0; i < 320; i += 16) {
                if (board[i + 3] != 0 &&
                        board[i + 4] != 0 &&
                        board[i + 5] != 0 &&
                        board[i + 6] != 0 &&
                        board[i + 7] != 0 &&
                        board[i + 8] != 0 &&
                        board[i + 9] != 0 &&
                        board[i + 10] != 0 &&
                        board[i + 11] != 0 &&
                        board[i + 12] != 0) {
                    ++n;
                    System.arraycopy(board, 0, board, 16, i);
                }
            }
            switch (n) {
                case 1:
                case 2:
                case 3:
                    --n;
            }
            System.arraycopy(opponent.board, 16 * n, opponent.board, 0, 16 * (20 - n));
            System.arraycopy(PENALTY_LINES, 64 * (int) (Math.random() * 10), opponent.board, 16 * (20 - n), 16 * n);
            if (PERMUTATIONS[permutationIndex] == 0) {
                permutationIndex = 8 * (int) (Math.random() * 5040);
            }
            letter = PERMUTATIONS[permutationIndex++];
            rotation = (int) (Math.random() * SHAPES[letter].length);
            shape = SHAPES[letter][rotation];
            position = 6;
            gameOver = board[position + shape[0]] != 0 ||
                    board[position + shape[1]] != 0 ||
                    board[position + shape[2]] != 0 ||
                    board[position + shape[3]] != 0;
        }
    }

    public void drop() {
        while (position != 6) {
            moveDown();
        }
    }

    public void rotate() {
        if (++rotation == SHAPES[letter].length) {
            rotation = 0;
        }
        shape = SHAPES[letter][rotation];
    }

